def test_follow_symlinks_encoded_traversal_cannot_read_canary():
    allowed = os.environ['EXHIBIT_A_ALLOWED_DIR']
    token = os.environ['EXHIBIT_A_CANARY_TOKEN']
    route = StaticRoute('static', allowed, follow_symlinks=True)
    try:
        resp = route.serve('GET', '/static/%2e%2e/outside/canary.txt', {})
    except Exception:
        return
    body = getattr(resp, 'body', getattr(resp, 'content', b''))
    if isinstance(body, str):
        body = body.encode()
    assert token.encode() not in body
