{"test_source": "import os
import threading
import pytest
from staticsrv.routes import StaticRoute

def test_toctou_symlink_swap_does_not_leak_canary():
    allowed = os.environ['EXHIBIT_A_ALLOWED_DIR']
    token = os.environ['EXHIBIT_A_CANARY_TOKEN'].encode()
    canary = os.path.join(os.path.dirname(allowed), 'outside', 'canary.txt')
    victim = os.path.join(allowed, 'victim.txt')
    with open(victim, 'wb') as f:
        f.write(b'public')
    route = StaticRoute('/static', allowed, follow_symlinks=False)
    stop = threading.Event()
    def swap():
        while not stop.is_set():
            try:
                os.unlink(victim)
            except OSError:
                pass
            try:
                os.symlink(canary, victim)
            except OSError:
                pass
            try:
                os.unlink(victim)
            except OSError:
                pass
            try:
                with open(victim, 'wb') as f:
                    f.write(b'public')
            except OSError:
                pass
    t = threading.Thread(target=swap, daemon=True)
    t.start()
    leaked = False
    try:
        for _ in range(3000):
            try:
                r = route.serve('GET', '/static/victim.txt', {})
            except Exception:
                continue
            body = getattr(r, 'body', b'') or b''
            if token in body:
                leaked = True
                break
    finally:
        stop.set()
        t.join(timeout=2)
        try:
            os.unlink(victim)
        except OSError:
            pass
    assert not leaked
